function strategy(series, index) {
  const high20 = Math.max(...series.slice(Math.max(0, index - 20), index).map(bar => bar.high));
  const low10 = Math.min(...series.slice(Math.max(0, index - 10), index).map(bar => bar.low));
  const current = series[index];
  const buyRule = current.close > high20;
  const sellRule = current.close < low10;
  return { buyRule, sellRule };
}

function strategy(series, index) {
  if (index < 26) return { buyRule: false, sellRule: false };
  const ema12 = indicators.ema(series, 12, index);
  const ema26 = indicators.ema(series, 26, index);
  const prevEma12 = indicators.ema(series, 12, index - 1);
  const prevEma26 = indicators.ema(series, 26, index - 1);
  const buyRule = prevEma12 <= prevEma26 && ema12 > ema26;
  const sellRule = prevEma12 >= prevEma26 && ema12 < ema26;
  return { buyRule, sellRule };
}

function strategy(series, index) {
  const st = indicators.superTrend(series, 10, 3.0, index);
  const prevSt = indicators.superTrend(series, 10, 3.0, index - 1);
  const buyRule = prevSt.direction === -1 && st.direction === 1;
  const sellRule = prevSt.direction === 1 && st.direction === -1;
  return { buyRule, sellRule };
}

function strategy(series, index) {
  if (index < 120) return { buyRule: false, sellRule: false };
  const ma20 = indicators.sma(series, 20, index);
  const ma50 = indicators.sma(series, 50, index);
  const ma120 = indicators.sma(series, 120, index);
  const close = series[index].close;
  const buyRule = (ma20 > ma50 && ma50 > ma120) && (close > ma20);
  const sellRule = close < ma50;
  return { buyRule, sellRule };
}

function strategy(series, index) {
  const sar = indicators.sar(series, 0.02, 0.2, index);
  const prevSar = indicators.sar(series, 0.02, 0.2, index - 1);
  const close = series[index].close;
  const prevClose = series[index - 1].close;
  const buyRule = prevClose < prevSar && close > sar;
  const sellRule = prevClose > prevSar && close < sar;
  return { buyRule, sellRule };
}

function strategy(series, index) {
  const ichi = indicators.ichimoku(series, 9, 26, 52, index);
  const close = series[index].close;
  const inCloud = close >= Math.min(ichi.spanA, ichi.spanB) && close <= Math.max(ichi.spanA, ichi.spanB);
  const aboveCloud = close > Math.max(ichi.spanA, ichi.spanB);
  const buyRule = aboveCloud && (ichi.tenkan > ichi.kijun);
  const sellRule = close < ichi.kijun || inCloud;
  return { buyRule, sellRule };
}

function strategy(series, index) {
  const bb = indicators.bollingerBands(series, 20, 2.0, index);
  const rsi = indicators.rsi(series, 14, index);
  const close = series[index].close;
  const buyRule = close < bb.lower && rsi < 30;
  const sellRule = close >= bb.middle || rsi > 65;
  return { buyRule, sellRule };
}

function strategy(series, index) {
  if (index < 20) return { buyRule: false, sellRule: false };
  const rsiCurrent = indicators.rsi(series, 14, index);
  const rsiPrevLow = Math.min(...indicators.rsiSeries(series, 14, index - 10, index - 1));
  const priceCurrent = series[index].low;
  const pricePrevLow = Math.min(...series.slice(index - 10, index).map(b => b.low));
  const buyRule = priceCurrent < pricePrevLow && rsiCurrent > rsiPrevLow && rsiCurrent < 35;
  const sellRule = rsiCurrent > 70 || (series[index].close < series[index - 1].close * 0.97);
  return { buyRule, sellRule };
}

function strategy(series, index) {
  const kdj = indicators.kdj(series, 9, 3, 3, index);
  const prevKdj = indicators.kdj(series, 9, 3, 3, index - 1);
  const buyRule = prevKdj.j < 0 && kdj.j > prevKdj.j && kdj.k > kdj.d;
  const sellRule = kdj.j > 90 || (prevKdj.k >= prevKdj.d && kdj.k < kdj.d);
  return { buyRule, sellRule };
}

function strategy(series, index) {
  const cci = indicators.cci(series, 20, index);
  const prevCci = indicators.cci(series, 20, index - 1);
  const buyRule = prevCci < -150 && cci > -100;
  const sellRule = cci > 100 || cci < prevCci - 30;
  return { buyRule, sellRule };
}

function strategy(series, index) {
  const kc = indicators.keltnerChannels(series, 20, 1.5, index);
  const current = series[index];
  const prev = series[index - 1];
  const buyRule = prev.close < kc.lower && current.close > current.open && current.close > kc.lower;
  const sellRule = current.close >= kc.middle || current.close >= kc.upper;
  return { buyRule, sellRule };
}

function strategy(series, index) {
  const wr = indicators.williamsR(series, 14, index);
  const prevWr = indicators.williamsR(series, 14, index - 1);
  const buyRule = prevWr <= -90 && wr > -80;
  const sellRule = wr >= -20 || (index - series.entryIndex >= 3);
  return { buyRule, sellRule };
}

function strategy(series, index) {
  const atr = indicators.atr(series, 14, index);
  const gridBase = series[index - 1].close;
  const currentPrice = series[index].close;
  const buyRule = currentPrice <= gridBase - atr * 0.8;
  const sellRule = currentPrice >= gridBase + atr * 1.2;
  return { buyRule, sellRule };
}

function strategy(series, index) {
  const boxHigh = Math.max(...series.slice(index - 30, index).map(b => b.high));
  const boxLow = Math.min(...series.slice(index - 30, index).map(b => b.low));
  const close = series[index].close;
  const buyRule = close <= boxLow * 1.015 && close >= boxLow;
  const sellRule = close >= boxHigh * 0.985;
  return { buyRule, sellRule };
}

function strategy(series, index, position) {
  const currentPrice = series[index].close;
  const avgCost = position.avgPrice || currentPrice;
  const buyRule = !position.hasPosition || (currentPrice <= avgCost * 0.975);
  const sellRule = position.hasPosition && (currentPrice >= avgCost * 1.025);
  return { buyRule, sellRule };
}

function strategy(series, index) {
  const pp = indicators.pivotPoints(series[index - 1]);
  const close = series[index].close;
  const buyRule = close <= pp.s1 && close > pp.s2;
  const sellRule = close >= pp.r1;
  return { buyRule, sellRule };
}

function strategy(series, index) {
  const volMa5 = indicators.sma(series.map(b => b.volume), 5, index);
  const high20 = Math.max(...series.slice(index - 20, index).map(b => b.high));
  const current = series[index];
  const buyRule = current.volume > volMa5 * 2.0 && current.close > high20 && current.close > current.open;
  const sellRule = current.close < series[index - 1].low || (current.close < current.open * 0.96);
  return { buyRule, sellRule };
}

function strategy(series, index) {
  const bb = indicators.bollingerBands(series, 20, 2.0, index);
  const bandwidth = (bb.upper - bb.lower) / bb.middle;
  const minBw = Math.min(...indicators.bandwidthSeries(series, 20, index - 15, index - 1));
  const buyRule = bandwidth > minBw && series[index].close > bb.upper && series[index].volume > series[index - 1].volume;
  const sellRule = series[index].close < bb.middle;
  return { buyRule, sellRule };
}

function strategy(series, index) {
  if (index < 55) return { buyRule: false, sellRule: false };
  const dcUpper55 = Math.max(...series.slice(index - 55, index).map(b => b.high));
  const dcLower20 = Math.min(...series.slice(index - 20, index).map(b => b.low));
  const current = series[index];
  const buyRule = current.close > dcUpper55;
  const sellRule = current.close < dcLower20;
  return { buyRule, sellRule };
}

function strategy(series, index) {
  const obv = indicators.obv(series, index);
  const obvMa = indicators.obvMa(series, 20, index);
  const ma20 = indicators.sma(series, 20, index);
  const buyRule = obv > obvMa && series[index].close > ma20 && series[index - 1].close <= ma20;
  const sellRule = obv < obvMa || series[index].close < ma20;
  return { buyRule, sellRule };
}

function strategy(series, index) {
  const prev = series[index - 1];
  const current = series[index];
  const gapUp = current.low > prev.high * 1.015;
  const strongClose = current.close >= current.open;
  const buyRule = gapUp && strongClose;
  const sellRule = current.close < prev.high || (current.close < current.open * 0.97);
  return { buyRule, sellRule };
}

function strategy(series, index) {
  const fractalHigh = indicators.fractalUpper(series, index - 1);
  const fractalLow = indicators.fractalLower(series, index - 1);
  const close = series[index].close;
  const buyRule = close > fractalHigh && series[index - 1].close <= fractalHigh;
  const sellRule = close < fractalLow;
  return { buyRule, sellRule };
}

function strategy(series, index) {
  const regime = indicators.hmmRegime(series, index);
  const microMomentum = indicators.volWeightedMomentum(series, 5, index);
  const buyRule = regime.state === 'BULLISH_TREND' && microMomentum > 0.015;
  const sellRule = regime.state !== 'BULLISH_TREND' || microMomentum < -0.005;
  return { buyRule, sellRule };
}

function strategy(series, index) {
  const zscore = indicators.residualZScore(series, index, 30);
  const buyRule = zscore <= -2.5;
  const sellRule = zscore >= 0.0 || zscore <= -4.0;
  return { buyRule, sellRule };
}

function strategy(series, index, benchSeries) {
  const absMom = (series[index].close - series[index - 12].close) / series[index - 12].close;
  const relMom = indicators.relativeStrengthRank(series, benchSeries, 20, index);
  const buyRule = absMom > 0.03 && relMom > 0.90;
  const sellRule = absMom <= 0 || relMom < 0.70;
  return { buyRule, sellRule };
}

function strategy(series, index) {
  const vcp = indicators.vcpPattern(series, index);
  const close = series[index].close;
  const vol = series[index].volume;
  const buyRule = vcp.isDetected && close > vcp.pivotPrice && vol > vcp.avgVol * 1.5;
  const sellRule = close < vcp.pivotPrice * 0.95 || close > vcp.pivotPrice * 1.20;
  return { buyRule, sellRule };
}

function strategy(series, index) {
  const cupHandle = indicators.cupWithHandle(series, index);
  const current = series[index];
  const volMa50 = indicators.sma(series.map(b => b.volume), 50, index);
  const buyRule = cupHandle.completed && current.close > cupHandle.pivot && current.volume > volMa50 * 1.5;
  const sellRule = current.close < cupHandle.pivot * 0.93 || current.close > cupHandle.pivot * 1.25;
  return { buyRule, sellRule };
}

function strategy(series, index) {
  const vol = indicators.historicalVolatility(series, 20, index);
  const mom = (series[index].close - series[index - 20].close) / series[index - 20].close;
  const buyRule = vol < 0.18 && mom > 0.02;
  const sellRule = vol > 0.35 || mom < -0.01;
  return { buyRule, sellRule };
}

function strategy(series, index, position) {
  const ma60 = indicators.sma(series, 60, index);
  const atr = indicators.atr(series, 14, index);
  const close = series[index].close;
  const initialBuy = !position.hasPosition && close > ma60 && series[index - 1].close <= ma60;
  const addPosition = position.hasPosition && close >= position.lastPrice + atr && position.addCount < 3;
  const buyRule = initialBuy || addPosition;
  const sellRule = position.hasPosition && (close < position.entryPrice || close < indicators.sma(series, 20, index));
  return { buyRule, sellRule };
}

function strategy(series, index) {
  const ofi = indicators.orderFlowImbalance(series, 5, index);
  const delta = indicators.cumulativeVolumeDelta(series, index);
  const buyRule = ofi > 2.5 && delta.slope > 0 && series[index].close > series[index].open;
  const sellRule = ofi < -1.0 || delta.slope < 0;
  return { buyRule, sellRule };
}
